struct blob_entry {
    int h[2];
    int edge;
};

struct blob {
    vector<blob_entry> entries;
    vector<int> sizes;
};

vector<vi> edges;
vi cols;
vector<blob> blobs;

int do_color(int i, int col) {
    if (cols[i] != -1) {
        return cols[i] == col;
    }
    cols[i] = col;
    for (int j : edges[i]) {
        if (!do_color(j, 1 - col)) {
            return 0;
        }
    }
    return 1;
}

void make_blobs(const vector<pii> &pairs) {
    int n = 0;
    for (auto p : pairs) {
        n = max(n, max(p.first, p.second) + 1);
    }
    edges.assign(n, vi());
    cols.assign(n, -1);
    for (auto p : pairs) {
        edges[p.first].push_back(p.second);
        edges[p.second].push_back(p.first);
    }
    for (int i = 0; i < n; i++) {
        if (cols[i] == -1) {
            blob b;
            if (!do_color(i, 0)) {
                assert(false);
            }
            for (int j = 0; j < n; j++) {
                if (cols[j] == 0) {
                    b.sizes.push_back(1);
                    b.entries.push_back({j, -1, -1});
                }
            }
            for (int j = 0; j < n; j++) {
                if (cols[j] == 1) {
                    int m = b.sizes.size();
                    for (int k = 0; k < m; k++) {
                        if (find(edges[j].begin(), edges[j].end(), b.entries[k].h[0]) != edges[j].end()) {
                            b.entries.push_back({j, b.entries[k].h[0], k});
                            b.sizes[k]++;
                            break;
                        }
                    }
                }
            }
            blobs.push_back(b);
        }
    }
}

void unify_sizes(vector<int> &sizes1, const vector<int> &sizes2, int ofs1, int ofs2) {
    int m = sizes1.size();
    int n = sizes2.size();
    for (int i = 0; i < m; i++) {
        sizes1[i] += ofs1;
    }
    for (int i = 0; i < n; i++) {
        sizes2[i] += ofs2;
    }
    int cost = accumulate(RA(sizes1), 0) + accumulate(RA(sizes2), 0);
    for (int i = 0, j = 0; i < m || j < n;) {
        if (j == n || (i < m && sizes1[i] < sizes2[j])) {
            cost += sizes1[i++];
        } else {
            cost += sizes2[j++];
        }
    }
    cout << cost << endl;
    sizes1.resize(m + n);
    merge(RA(sizes1.begin(), m), RA(sizes2), sizes1.begin(), greater<int>());
}

