        int m = blobs.size();
        vector<int> sizes(m);
        for (int i = 0; i < m; i++) {
            sizes[i] = blobs[i].sizes.size();
        }
        for (int i = 0; i < m - 1; i++) {
            unify_sizes(sizes, blobs[i + 1].sizes, 0, 0);
        }
        blobs.clear();
    }
