int rows, cols, grid[10][10], temp_grid[10][10];
int dx[9] = {0, 0, 1, -1, 0, -1, -1, 1, 1}, dy[9] = {0, 1, 0, 0, -1, -1, 1, -1, 1};

// Load input data from file
void LoadData() {
    ifstream input_file("input.txt");
    input_file >> rows >> cols;
    for (int i = 0; i < rows; i++)
        for (int j = 0; j < cols; j++)
            input_file >> grid[i][j];
    input_file.close();
}

// Solve the problem and return the maximum number of cells set to 1 in the middle row
int SolveProblem() {
    int max_ones_in_middle_row = 0;
    for (int mask = 0; mask < (1 << (rows * cols)); mask++) {
        // Create a temporary grid based on the current mask
        for (int i = 0; i < rows; i++)
            for (int j = 0; j < cols; j++)
                temp_grid[i][j] = (mask & (1 << (i * cols + j))) > 0;

        bool is_valid = true;
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                int neighbor_count = 0;
                // Check all neighboring cells
                for (int k = 0; k < 9; k++) {
                    int x = i + dx[k], y = j + dy[k];
                    if (x >= 0 && x < rows && y >= 0 && y < cols)
                        neighbor_count += temp_grid[x][y];
                }
                // If the neighbor count doesn't match the grid value, the current mask is invalid
                if (neighbor_count != grid[i][j]) {
                    is_valid = false;
                    break;
                }
            }
            if (!is_valid) break;
        }

        // If the current mask is valid, count the number of ones in the middle row
        if (is_valid) {
            int ones_in_middle_row = 0;
            for (int j = 0; j < cols; j++)
                ones_in_middle_row += temp_grid[rows / 2][j];
            max_ones_in_middle_row = max(max_ones_in_middle_row, ones_in_middle_row);
        }
    }
    return max_ones_in_middle_row;
}

