    Edge* reverse_edge;
};

int num_nodes, source, sink, excess[MAX_NODES], height[MAX_NODES];
vector<Edge> graph[MAX_NODES];
vector<int> current_edge(MAX_NODES);

void breadth_first_search(int start_node, int start_height) {
    queue<int> queue;
    memset(height, -1, sizeof height);
    height[start_node] = start_height;
    queue.push(start_node);
    while (!queue.empty()) {
        int current_node = queue.front();
        queue.pop();
        for (Edge &edge : graph[current_node]) {
            if (edge.capacity - edge.flow > 0 && height[edge.destination] == -1) {
                height[edge.destination] = height[current_node] + 1;
                queue.push(edge.destination);
            }
        }
    }
}

void compute_max_flow() {
    memset(excess, 0, sizeof excess);
    breadth_first_search(source, 0);
    while (true) {
        bool pushed = false;
        ITERATE_OVER(current_node, num_nodes) {
            if (excess[current_node] > 0 && current_node != source && current_node != sink) {
                for (int &edge_index = current_edge[current_node]; edge_index < (int)graph[current_node].size(); edge_index++) {
                    Edge &edge = graph[current_node][edge_index];
                    if (edge.capacity - edge.flow > 0 && height[current_node] > height[edge.destination]) {
                        int push_amount = min(excess[current_node], edge.capacity - edge.flow);
                        edge.flow += push_amount;
                        graph[edge.destination][edge.reverse_index].flow -= push_amount;
                        excess[current_node] -= push_amount;
                        excess[edge.destination] += push_amount;
                        pushed = true;
                    }
                }
            }
        }
        if (!pushed) {
            int current_node;
            for (current_node = 0; current_node < num_nodes; current_node++) {
                if (excess[current_node] > 0 && current_node != source && current_node != sink) {
                    int min_height = INT_MAX;
                    for (Edge &edge : graph[current_node]) {
                        if (edge.capacity - edge.flow > 0) {
                            min_height = min(min_height, height[edge.destination]);
                        }
                    }
                    if (min_height == INT_MAX) break;
                    height[current_node] = min_height + 1;
                }
            }
            if (current_node == num_nodes) break;
        }
    }
