using namespace std;
typedef long long ll;
const ll MOD = 1000000007;
const int MAX_SIZE = 100007;
ll factorial[MAX_SIZE], inverse_factorial[MAX_SIZE];

ll powerModulo(ll base, ll exponent) {
    ll result = 1;
    while (exponent) {
        if (exponent & 1) result = result * base % MOD;
        base = base * base % MOD;
        exponent >>= 1;
    }
    return result;
}

void precomputeFactorials() {
    factorial[0] = 1;
    for (int i = 1; i < MAX_SIZE; i++) factorial[i] = factorial[i - 1] * i % MOD;
    inverse_factorial[MAX_SIZE - 1] = powerModulo(factorial[MAX_SIZE - 1], MOD - 2);
    for (int i = MAX_SIZE - 2; i >= 0; i--) inverse_factorial[i] = inverse_factorial[i + 1] * (i + 1) % MOD;
}

ll combinationCount(ll x, int y) {
    return factorial[x] * inverse_factorial[y] % MOD * inverse_factorial[x - y] % MOD;
}

int primes[MAX_SIZE], isPrime[MAX_SIZE];

void generatePrimes() {
    for (int i = 2; i < MAX_SIZE; i++) {
        if (!isPrime[i]) primes[++primes[0]] = i;
        for (int j = 1; j <= primes[0] && i * primes[j] < MAX_SIZE; j++) {
            isPrime[i * primes[j]] = 1;
            if (i % primes[j] == 0) break;
        }
    }
}

int determineSign(int x) {
    int count = 0;
    for (int i = 1; primes[i] * primes[i] <= x; i++) {
        if (x % primes[i] == 0) {
            int tmp = 0;
            while (x % primes[i] == 0) {
                tmp++;
                x /= primes[i];
            }
            if (tmp > 1) return 0;
            count++;
        }
    }
    if (x > 1) count++;
    return count % 2 ? -1 : 1;
}

