    precomputeFactorials();
    for (n = 1; n <= 100000; n++) {
        ll result = 0;
        for (m = 1; m <= n; m++) {
            result = (result + combinationCount(n, m) * determineSign(m)) % MOD;
        }
        if (result < 0) printf("%d\n", n);
    }
    return 0;
