bool counterclockwise(const point &a, const point &b, const point &c) {
    return (b.first - a.first) * (c.second - a.second) - (b.second - a.second) * (c.first - a.first) < 0;
}

vector<point> convexHull(vector<point> points) {
    int numPoints = points.size();
    vector<point> hull;
    sort(points.begin(), points.end());
    for (int i = 0; i < numPoints; i++) {
        while (hull.size() >= 2 && !counterclockwise(hull[hull.size() - 2], hull.back(), points[i])) hull.pop_back();
        hull.push_back(points[i]);
    }
    int k = hull.size();
    for (int i = numPoints - 2; i >= 0; i--) {
        while (hull.size() > k && !counterclockwise(hull[hull.size() - 2], hull.back(), points[i])) hull.pop_back();
        hull.push_back(points[i]);
    }
    hull.pop_back();
    return hull;
}

bool onLine(point x, point a, point b) {
    return (x.first - a.first) * (b.second - a.second) == (x.second - a.second) * (b.first - a.first);
