nfa emptyNFA = nfa(1);
nfa zeroNFA = nfa(0);

nfa kleeneStarOf(nfa x) {
    nfa y = nfa(x.stateCount + 1);
    fore(i, 0, x.stateCount) fore(j, 0, x.stateCount) fore(k, 0, 256) y.transitions[i][j + 1][k] = x.transitions[i][j][k];
