    y.finalStates = x.finalStates;
    y.finalStates.insert(y.stateCount);
    return y;
}

nfa combineNFAs(nfa x, nfa y) {
    nfa z = nfa(x.stateCount + y.stateCount);
    fore(i, 0, x.stateCount) fore(j, 0, x.stateCount) fore(k, 0, 256) z.transitions[i][j][k] = x.transitions[i][j][k];
    fore(i, x.stateCount, x.stateCount + y.stateCount) fore(j, x.stateCount, x.stateCount + y.stateCount) fore(k, 0, 256) z.transitions[i][j][k] = y.transitions[i - x.stateCount][j - x.stateCount][k];
