    nfa x = nfa(sz(s) + 1);
    fore(i, 0, sz(s)) x.transitions[i][i + 1][s[i]] = 1;
    x.finalStates.insert(sz(s));
    return x;
}

nfa constructNFA(string &s, int &i) {
    if (s[i] == '(') {
        i++;
        nfa x = constructNFA(s, i);
        i++;
        return x;
    }
    if (s[i] == ')' || s[i] == '|') return zeroNFA;
    if (isalpha(s[i])) return stringToNFA(string(1, s[i++]));
    if (s[i] == '*') {
        i++;
        return kleeneStarOf(constructNFA(s, i));
    }
    vector<nfa> v;
    while (s[i] != ')' && s[i] != '|') v.pb(constructNFA(s, i));
