void solveSubproblem(int left, int right) {
    if (left > right)
        return;
    if (left == right) {
        updateStartIndex(queryIndices[left] + (sequence[left] != (prefixSum[n] - prefixSum[left] + sequence[left]) % 2));
        return;
    }
    int mid = (left + right) / 2;
    solveSubproblem(left, mid);
    memset(binaryIndexedTree, 0, sizeof binaryIndexedTree);
    for (int i = mid + 1; i <= right; i++)
        insertInBIT(1, compressedIndices[i]);
    for (int i = mid; i >= left; i--) {
        leftCounts[i] = queryBIT(compressedIndices[i]);
        rightCounts[i] = right - mid - leftCounts[i] + 1;
