        rightCounts[i] = queryBIT(compressedIndices[i] - 1);
    }
    for (int i = mid + 1; i <= right; i++)
        queryIndices[i] = leftCounts[i] + rightCounts[i] + queryIndices[i] + (sequence[i] != (prefixSum[i] - prefixSum[left]) % 2);
    compressIndices(queryIndices + mid + 1, compressedIndices + mid + 1);
