// Recursive function to find the minimum fuel required to reach the bottom-right corner
int findMinFuel(int row, int col, MOVE prevMove, vector<string> &matrix)
{
    // Check if the current position is out of bounds or a wall
    if (row >= numRows || col >= numCols || matrix[row][col] == '#')
        return -1; // Invalid position

    // If we have reached the bottom-right corner, no fuel is needed
    if (row == numRows - 1 && col == numCols - 1)
        return 0;

    int minFuel = 1e9; // Initialize with a large value

    // Try all possible moves from the current position
    if (prevMove != DOWN_RIGHT)
        minFuel = min(minFuel, findMinFuel(row, col + 1, RIGHT, matrix) + 1); // Move right
    if (prevMove != DOWN_LEFT)
        minFuel = min(minFuel, findMinFuel(row + 1, col, DOWN_RIGHT, matrix) + 1); // Move down-right
    if (prevMove != RIGHT)
        minFuel = min(minFuel, findMinFuel(row, col - 1, LEFT, matrix) + 1); // Move left
    if (prevMove != LEFT)
        minFuel = min(minFuel, findMinFuel(row - 1, col, DOWN_LEFT, matrix) + 1); // Move down-left

    // If no valid path is found, return -1
    if (minFuel == 1e9)
        return -1;

    // If the minimum fuel required is within the available fuel, return the value
    if (minFuel <= maxFuel)
        return minFuel;

    // Otherwise, return -1 to indicate an invalid path
    return -1;
}

