class DisjointSet {
private:
    VI parent, rank;

public:
    DisjointSet(int N) {
        rank.assign(N, 0);
        parent.resize(N);
        F0R(i, N) parent[i] = i;
    }

    int findRoot(int v) {
        if (parent[v] == v)
            return v;
        return parent[v] = findRoot(parent[v]);
    }

    void unite(int u, int v) {
        u = findRoot(u);
        v = findRoot(v);
        if (rank[u] < rank[v])
            swap(u, v);
        parent[v] = u;
        if (rank[u] == rank[v])
            rank[u]++;
    }

    int getNumSets() {
        int count = 0;
        F0R(i, sz(parent))
            if (parent[i] == i)
                count++;
        return count;
    }
};

