    if (P < 1025)
        return isPrime[P];
    for (int p : primes) {
        if (P % p == 0)
            return false;
        if (p * p > P)
            break;
    }
    return true;
}

int solve(int A, int B, int P) {
    DisjointSet ds(B - A + 1);
    for (int p = P; p * p <= B; p++) {
        if (!isPrime(p))
            continue;
        for (int x = max(A, p * p); x <= B; x += p)
            if (x - A >= 0)
                ds.unite(x - A, (x - A) / p);
    }
    return ds.getNumSets();
}

