#include <bits/stdc++.h>
using namespace std;

const int INF = 0x3f3f3f3f;

class Edge {
public:
    int destination, capacity, reverseEdgeIndex;
    Edge(int to, int cap, int rev) : destination(to), capacity(cap), reverseEdgeIndex(rev) {}
};

class FordFulkerson {
private:
    int numVertices;
    vector<vector<Edge>> graph;
    vector<int> levelGraph, pointerTracker;

    bool breadthFirstSearch(int source, int sink) {
        levelGraph.assign(numVertices, -1);
        queue<int> queue;
        levelGraph[source] = 0;
        queue.push(source);
        while (!queue.empty()) {
            int currentVertex = queue.front();
            queue.pop();
            for (const Edge &edge : graph[currentVertex]) {
                if (edge.capacity > 0 && levelGraph[edge.destination] == -1) {
                    levelGraph[edge.destination] = levelGraph[currentVertex] + 1;
                    queue.push(edge.destination);
                }
            }
        }
        return levelGraph[sink] != -1;
    }

    int depthFirstSearch(int currentVertex, int sink, int flowCapacity) {
        if (currentVertex == sink) return flowCapacity;
        for (int &i = pointerTracker[currentVertex]; i < (int)graph[currentVertex].size(); i++) {
            Edge &edge = graph[currentVertex][i];
            if (edge.capacity > 0 && levelGraph[edge.destination] == levelGraph[currentVertex] + 1) {
                int augmentedFlow = depthFirstSearch(edge.destination, sink, min(flowCapacity, edge.capacity));
                if (augmentedFlow > 0) {
                    edge.capacity -= augmentedFlow;
                    graph[edge.destination][edge.reverseEdgeIndex].capacity += augmentedFlow;
                    return augmentedFlow;
                }
            }
        }
        return 0;
    }

public:
    FordFulkerson(int numNodes) : numVertices(numNodes), graph(numNodes), pointerTracker(numNodes) {}

    void addEdge(int from, int to, int cap) {
        graph[from].emplace_back(to, cap, graph[to].size());
        graph[to].emplace_back(from, 0, graph[from].size() - 1);
    }

    int maxFlow(int source, int sink) {
        int maxFlowValue = 0;
        while (breadthFirstSearch(source, sink)) {
            pointerTracker.assign(numVertices, 0);
            while (int augmentedFlow = depthFirstSearch(source, sink, INF))
                maxFlowValue += augmentedFlow;
        }
        return maxFlowValue;
    }
};

