void findMaxSafeTime(vector<Vehicle>& vehicles, double currentTime, int currentVehicleIndex) {
    int leftVehicleIndex, rightVehicleIndex;
    leftVehicleIndex = rightVehicleIndex = -1;
    double minDistance = INFINITY, distance;
    for (int i = 0; i < numVehicles; i++) {
        if (i == currentVehicleIndex) continue;
        if (vehicles[i].isLeftward != vehicles[currentVehicleIndex].isLeftward) {
            distance = fabs(vehicles[i].position - vehicles[currentVehicleIndex].position + (vehicles[currentVehicleIndex].speed - vehicles[i].speed) * currentTime);
            if (distance < VEHICLE_LENGTH) {
                infinityFlag = 1;
                return;
            }
            if (distance < minDistance) {
                minDistance = distance;
                leftVehicleIndex = i;
                rightVehicleIndex = currentVehicleIndex;
                if (vehicles[i].isLeftward) swap(leftVehicleIndex, rightVehicleIndex);
            }
        }
    }
    if (minDistance == INFINITY) {
        maxSafeTime = max(maxSafeTime, currentTime);
        return;
    }
    double timeToCollision = (minDistance - VEHICLE_LENGTH) / (vehicles[rightVehicleIndex].speed + vehicles[leftVehicleIndex].speed);
    vehicles[rightVehicleIndex].position += vehicles[rightVehicleIndex].speed * timeToCollision;
    vehicles[leftVehicleIndex].position -= vehicles[leftVehicleIndex].speed * timeToCollision;
    findMaxSafeTime(vehicles, currentTime + timeToCollision, rightVehicleIndex);
    findMaxSafeTime(vehicles, currentTime + timeToCollision, leftVehicleIndex);
